        if (!c->cleanup_confirmed) c->state = VX_UNCERTAIN;
    }
    if (c->control_fd >= 0) close(c->control_fd);
    if (c->key_fd >= 0) close(c->key_fd);
    c->control_fd = c->key_fd = -1;
    if (c->used) record_retirement(c, c->cleanup_confirmed);
